declare(strict_types=1);
function icon(string $name): string {
    $paths=['grid'=>'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>','users'=>'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>','scan'=>'<path d="M4 8V4h4m8 0h4v4M4 16v4h4m8 0h4v-4M3 12h18"/>','calendar'=>'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>','arrow'=>'<path d="M5 12h14m-5-5 5 5-5 5"/>','plus'=>'<path d="M12 5v14M5 12h14"/>','check'=>'<path d="m5 12 4 4L19 6"/>','download'=>'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>','search'=>'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>','settings'=>'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>','clock'=>'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>','logout'=>'<path d="M9 4H4v16h5m5-13 5 5-5 5M9 12h11"/>','pin'=>'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>','qr'=>'<path d="M3 3h6v6H3zm12 0h6v6h-6zM3 15h6v6H3zm12 0h2v2h-2zm4 0h2v6h-4v-2h-2m-3-7v2m-9-2h6m6 0h6"/>'];
    return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['grid']).'</svg>';
}
function head(string $title): void { ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=e(csrf())?>"><title><?=e($title)?> · Hadir</title><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/app.css"><script src="assets/app.js" defer></script></head><body><?php }
function flash_view(): void {if($f=$_SESSION['flash']??null){unset($_SESSION['flash']);echo '<div class="notice '.e($f[1]).'" role="status">'.e($f[0]).'</div>';}}
function render_login(): void {head('Masuk');?><main class="auth-wrap"><div class="auth-story"><a class="brand" href="index.php"><span class="brand-icon"><?=icon('qr')?></span>hadir<span>.</span></a><div><div class="eyebrow">LESS WAITING, MORE WELCOMING</div><h1>Setiap tamu,<br>disambut baik.</h1><p>Satu undangan. Satu scan.<br>Lebih banyak waktu untuk momen yang berarti.</p><div class="story-mark"><?=icon('scan')?></div></div><small>Sederhana untuk panitia. Nyaman untuk tamu.</small></div><section class="auth-card"><div class="eyebrow">RUANG PANITIA</div><h1>Selamat datang kembali.</h1><p>Masuk untuk menyiapkan sambutan terbaik.</p><?php flash_view();?><form method="post" action="index.php"><?=csrf_field()?><input type="hidden" name="action" value="login"><label>Username<input name="username" required maxlength="50" autocomplete="username" placeholder="Username Anda" autofocus></label><label>Kata sandi<div class="password-field"><input id="login-password" name="password" type="password" required autocomplete="current-password" maxlength="72" placeholder="Kata sandi Anda"><button type="button" class="password-toggle" data-toggle-password="login-password" aria-label="Tampilkan kata sandi">Lihat</button></div></label><button class="btn primary full">Masuk ke ruang acara <?=icon('arrow')?></button></form><p class="fine">Lupa kata sandi? Hubungi superadmin sistem.</p></section></main></body></html><?php }
function render_header(string $page): void {define('LAYOUT_OPEN',true);$u=user();$ev=selected_event();$labels=['dashboard'=>'Ringkasan','events'=>'Acara','guests'=>'Daftar tamu','scan'=>'Scan QR','users'=>'Tim & akses','logs'=>'Aktivitas','account'=>'Akun saya'];head($labels[$page]??'Hadir');?><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-icon"><?=icon('qr')?></span>hadir<span>.</span></a><div class="workspace"><span class="workspace-icon"><?=icon('calendar')?></span><div><b><?=e($u['role']==='superadmin'?'Semua acara':($ev['name']??'Ruang acara'))?></b><small><?=e(['superadmin'=>'Pemilik sistem','admin'=>'Ketua acara','petugas'=>'Petugas registrasi'][$u['role']])?></small></div><span class="dot"></span></div><div class="nav-label">WORKSPACE</div><nav><?php foreach(['dashboard'=>['grid','Ringkasan'],'events'=>['calendar','Acara'],'guests'=>['users','Daftar tamu'],'scan'=>['scan','Scan QR'],'users'=>['settings','Tim & akses'],'logs'=>['clock','Aktivitas']] as $key=>[$ico,$name]):if($u['role']==='petugas'&&in_array($key,['events','users','logs']))continue;?><a class="nav-link <?=$page===$key?'active':''?>" href="<?=e(url($key,$ev?['event'=>$ev['id']]:[]))?>"><?=icon($ico)?><span><?=e($name)?></span><?= $key==='scan'?'<small class="live-tag">LIVE</small>':''?></a><?php endforeach;?></nav><div class="sidebar-bottom"><div class="slogan"><span>✳</span><h3>Sambutan dimulai<br>dari sini.</h3><p>Satu QR untuk setiap tamu.<br>Satu scan untuk hadir.</p></div><a class="profile" href="<?=e(url('account'))?>"><span class="avatar"><?=e(strtoupper(substr($u['name'],0,1)))?></span><div><b><?=e($u['name'])?></b><small><?=e($u['role'])?></small></div><?=icon('settings')?></a></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">Workspace <span>/</span> <b><?=e($labels[$page]??'Hadir')?></b></span><form action="index.php" method="post"><?=csrf_field()?><input type="hidden" name="action" value="logout"><button class="logout" title="Keluar"><?=icon('logout')?> <span>Keluar</span></button></form></header><div class="content"><?php flash_view();if($u['role']==='superadmin'&&in_array($page,['dashboard','guests','scan','logs'])): $opts=sql('SELECT id,name,status FROM events ORDER BY id DESC LIMIT 500')->fetchAll();?><form class="event-picker" method="get"><input type="hidden" name="page" value="<?=e($page)?>"><label for="choose-event">ACARA</label><select id="choose-event" name="event"><option value="">Pilih acara…</option><?php foreach($opts as $o):?><option value="<?=$o['id']?>" <?=$ev&&(int)$ev['id']===(int)$o['id']?'selected':''?>><?=e($o['name'].($o['status']==='archived'?' · Arsip':''))?></option><?php endforeach;?></select><button class="btn small ghost">Buka <?=icon('arrow')?></button></form><?php endif; }
function render_footer(): void {?></div><footer><span><b>hadir.</b> Less waiting, more welcoming.</span><span>Ringan. Rapi. Siap menyambut.</span></footer></main></div><div id="toast" class="toast" role="status" hidden></div></body></html><?php }
function page_heading(string $eyebrow,string $title,string $subtitle,string $action=''): void {echo '<div class="page-heading"><div><div class="eyebrow">'.e($eyebrow).'</div><h1>'.e($title).'</h1><p>'.e($subtitle).'</p></div>'.$action.'</div>';}
function empty_panel(string $title,string $desc,string $link=''): void {echo '<section class="panel empty"><span class="big-icon">'.icon('calendar').'</span><h2>'.e($title).'</h2><p>'.e($desc).'</p>'.$link.'</section>';}
function event_banner(array $ev): void { ?><section class="event-banner"><span class="event-art"><?=icon('calendar')?></span><div><div class="eyebrow">ACARA <?=$ev['status']==='active'?'AKTIF':'DIARSIPKAN'?></div><h2><?=e($ev['name'])?></h2><div class="event-meta"><span><?=icon('calendar')?><?=e($ev['starts_at']?date_time($ev['starts_at']):'Tanggal belum diatur')?></span><span><?=icon('pin')?><?=e($ev['location']?:'Lokasi belum diatur')?></span></div></div><span class="banner-decor">✳</span></section><?php if($ev['status']==='archived')echo '<div class="notice">Acara diarsipkan. Data dapat dilihat, tetapi perubahan tamu dan check-in ditutup.</div>'; }
function stats(array $s): void {$total=(int)$s['total'];$present=(int)$s['present'];$pct=$total?round($present/$total*100):0;?><div class="stats"><?php foreach([['Total undangan',$total,'users','Setiap tamu punya QR unik'],['Sudah hadir',$present,'check','Kehadiran tercatat langsung'],['Belum hadir',$total-$present,'clock','Menunggu kedatangan tamu'],['Tingkat kehadiran',$pct.'%','arrow','Dari seluruh tamu undangan']] as [$label,$value,$ico,$note]):?><section class="stat"><div><span><?=e($label)?></span><?=icon($ico)?></div><strong><?=e($value)?></strong><small><?=e($note)?></small></section><?php endforeach;?></div><?php }
function guest_stats(int $id): array {return sql('SELECT COUNT(*) total,COALESCE(SUM(checked_at IS NOT NULL),0) present FROM guests WHERE event_id=? AND deleted_at IS NULL',[$id])->fetch();}
function render_dashboard(): void {
 $u=user();$ev=selected_event();page_heading('EVENT MANAGEMENT, MADE SIMPLE','Setiap tamu, disambut baik.','Kelola undangan dan catat kehadiran tanpa ribet.');
 if(!$ev){$n=sql('SELECT COUNT(*) FROM events')->fetchColumn();$users=sql('SELECT COUNT(*) FROM users WHERE active=1')->fetchColumn();$s=sql('SELECT COUNT(*) total,COALESCE(SUM(checked_at IS NOT NULL),0) present FROM guests WHERE deleted_at IS NULL')->fetch();?><div class="overview-strip"><b><?=$n?> acara</b><span>·</span><b><?=$users?> akun aktif</b><a href="<?=e(url('events'))?>">Kelola acara <?=icon('arrow')?></a></div><?php stats($s);empty_panel('Satu tempat untuk semua acara.','Pilih acara di atas untuk melihat daftar tamu dan membuka scanner.','<a class="btn primary" href="'.e(url('events')).'">'.icon('plus').' Kelola acara</a>');return;}
 event_banner($ev);stats(guest_stats((int)$ev['id']));$recent=sql('SELECT g.name,g.category,g.checked_at,u.name officer FROM guests g LEFT JOIN users u ON u.id=g.checked_by WHERE g.event_id=? AND g.deleted_at IS NULL AND g.checked_at IS NOT NULL ORDER BY g.checked_at DESC,g.id DESC LIMIT 8',[$ev['id']])->fetchAll();?><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Kedatangan terakhir</h2><p>Sambutan hangat, registrasi singkat.</p></div><span class="badge present"><i class="dot"></i> Kehadiran</span></div><?php if(!$recent):?><div class="empty"><span class="big-icon"><?=icon('users')?></span><h3>Belum ada tamu yang datang</h3><p>Kehadiran pertama akan muncul di sini.</p></div><?php else:?><div class="table-scroll"><table><thead><tr><th>Nama tamu</th><th>Waktu hadir</th><th>Petugas</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['category'])?></small></td><td><?=e(date_time($r['checked_at'],'H:i:s'))?></td><td><?=e($r['officer'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><div class="panel-foot"><a href="<?=e(url('guests',['event'=>$ev['id']]))?>">Lihat semua tamu <?=icon('arrow')?></a><small>Muat ulang untuk pembaruan terbaru.</small></div></section><section class="quick-panel"><span class="scan-art"><?=icon('qr')?></span><div class="eyebrow">SIAP MENYAMBUT TAMU?</div><h2>Check-in dalam<br>hitungan detik.</h2><p>Arahkan kamera ke QR undangan.<br>Kehadiran tersimpan otomatis.</p><a class="btn primary full" href="<?=e(url('scan',['event'=>$ev['id']]))?>"><?=icon('scan')?> Buka scanner <?=icon('arrow')?></a><small>✓ Scan ulang otomatis dicegah</small><?php if($u['role']!=='petugas'):?><a class="btn ghost full" href="<?=e(url('guests',['event'=>$ev['id']]))?>">Kelola undangan</a><?php endif;?></section></div><?php
}
function dialog_start(string $id,string $title): void {echo '<dialog id="'.e($id).'"><div class="dialog-head"><h2>'.e($title).'</h2><button class="close" type="button" data-close aria-label="Tutup">×</button></div>';}
function dialog_end(): void {echo '</dialog>';}
function render_events(): void {
 $u=user();$edit=null;if(!empty($_GET['edit']))$edit=event_access((int)$_GET['edit'],true);
 page_heading('RUANG ACARA','Momen berbeda. Tetap tertata.','Atur detail acara dan tim yang bertugas.',$u['role']==='superadmin'?'<button class="btn primary" data-dialog="event-form">'.icon('plus').' Buat acara</button>':'');
 $events=$u['role']==='superadmin'?sql('SELECT e.*,(SELECT COUNT(*) FROM guests g WHERE g.event_id=e.id AND g.deleted_at IS NULL) guest_count FROM events e ORDER BY id DESC LIMIT 500')->fetchAll():sql('SELECT e.*,(SELECT COUNT(*) FROM guests g WHERE g.event_id=e.id AND g.deleted_at IS NULL) guest_count FROM events e WHERE id=?',[$u['event_id']])->fetchAll();
 if(!$events)empty_panel('Acara pertama Anda dimulai di sini.','Klik Buat acara untuk menambahkan nama, waktu, dan tempat.');
 echo '<div class="event-grid">';foreach($events as $ev):?><section class="panel event-card"><div class="card-top"><span class="event-icon"><?=icon('calendar')?></span><span class="badge <?=$ev['status']==='active'?'present':'waiting'?>"><?=$ev['status']==='active'?'Aktif':'Arsip'?></span></div><h2><?=e($ev['name'])?></h2><p><?=icon('calendar')?> <?=e($ev['starts_at']?date_time($ev['starts_at']):'Tanggal belum diatur')?></p><p><?=icon('pin')?> <?=e($ev['location']?:'Lokasi belum diatur')?></p><div class="card-count"><b><?=$ev['guest_count']?></b> tamu undangan</div><div class="card-actions"><a class="btn primary small" href="<?=e(url('dashboard',['event'=>$ev['id']]))?>">Buka acara <?=icon('arrow')?></a><a class="btn ghost small" href="<?=e(url('events',['edit'=>$ev['id'],'event'=>$ev['id']]))?>">Edit</a><?php if($u['role']==='superadmin'):?><form method="post" data-confirm="<?=$ev['status']==='active'?'Arsipkan acara? Check-in dan perubahan tamu akan ditutup.':'Aktifkan kembali acara ini?'?>"><?=csrf_field()?><input type="hidden" name="action" value="event_status"><input type="hidden" name="event_id" value="<?=$ev['id']?>"><button class="text-button"><?=$ev['status']==='active'?'Arsipkan':'Aktifkan'?></button></form><?php endif;?></div></section><?php endforeach;echo '</div>';
 dialog_start('event-form',$edit?'Edit acara':'Buat acara baru');?><form method="post" <?=$edit?'data-auto-open':''?>><?=csrf_field()?><input type="hidden" name="action" value="event_save"><input type="hidden" name="event_id" value="<?=e($edit['id']??0)?>"><label>Nama acara<input name="name" required maxlength="160" value="<?=e($edit['name']??'')?>" placeholder="Contoh: Holistik Fest 2026"></label><label>Waktu acara (<?=e(date_default_timezone_get())?>)<input name="starts_at" type="datetime-local" value="<?=e(isset($edit['starts_at'])?date_time($edit['starts_at'],'Y-m-d\TH:i'):'')?>"></label><label>Lokasi<input name="location" maxlength="200" value="<?=e($edit['location']??'')?>" placeholder="Nama tempat acara"></label><label>Catatan singkat<textarea name="description" maxlength="500" rows="3"><?=e($edit['description']??'')?></textarea></label><button class="btn primary full">Simpan acara <?=icon('check')?></button></form><?php dialog_end();
}
function render_guests(): void {
 $u=user();$ev=selected_event();$manage=$u['role']!=='petugas';if(!$ev){empty_panel('Pilih acara terlebih dahulu.','Gunakan pilihan acara di atas untuk membuka daftar tamu.');return;}$eid=(int)$ev['id'];$active=$ev['status']==='active';
 page_heading('UNDANGAN & KEHADIRAN','Semua tamu, satu tempat.',$ev['name'],$manage&&$active?'<button class="btn primary" data-dialog="guest-form">'.icon('plus').' Tambah tamu</button>':'');
 stats(guest_stats($eid));
 $q=trim((string)($_GET['q']??''));$q=substr($q,0,160);$status=(string)($_GET['status']??'all');$where='event_id=? AND deleted_at IS NULL';$args=[$eid];if($q!==''){$where.=' AND (name LIKE ? OR category LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if($status==='present')$where.=' AND checked_at IS NOT NULL';elseif($status==='waiting')$where.=' AND checked_at IS NULL';
 $total=(int)sql('SELECT COUNT(*) FROM guests WHERE '.$where,$args)->fetchColumn();$pages=max(1,(int)ceil($total/25));$page=max(1,min($pages,(int)($_GET['p']??1)));$offset=($page-1)*25;$rows=sql('SELECT * FROM guests WHERE '.$where.' ORDER BY id DESC LIMIT 25 OFFSET '.$offset,$args)->fetchAll();
 $edit=null;if($manage&&!empty($_GET['edit'])){$edit=sql('SELECT * FROM guests WHERE id=? AND event_id=? AND deleted_at IS NULL',[(int)$_GET['edit'],$eid])->fetch();if(!$edit)throw new DomainException('Tamu tidak ditemukan.');}
 ?><section class="panel"><div class="panel-heading"><div><h2>Daftar tamu <span class="count"><?=$total?></span></h2><p>QR unik untuk setiap undangan.</p></div><div class="inline-actions"><?php if($manage):?><a class="btn small ghost" href="<?=e(url('export',['event'=>$eid]))?>"><?=icon('download')?> Ekspor CSV</a><?php if($active):?><button class="btn small ghost" data-dialog="import-form">Impor CSV</button><?php endif;endif;?></div></div><form class="table-tools" method="get"><input type="hidden" name="page" value="guests"><input type="hidden" name="event" value="<?=$eid?>"><div class="search"><?=icon('search')?><input name="q" placeholder="Cari nama atau kategori…" value="<?=e($q)?>" aria-label="Cari tamu" maxlength="160"></div><select name="status" aria-label="Filter status"><?php foreach(['all'=>'Semua status','present'=>'Sudah hadir','waiting'=>'Belum hadir'] as $v=>$t):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$t?></option><?php endforeach;?></select><button class="btn small ghost">Cari</button></form><div class="table-scroll"><table><thead><tr><th>Nama tamu</th><th>Status</th><th>Undangan</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $g):?><tr><td><div class="guest-name"><span class="avatar"><?=e(strtoupper(substr($g['name'],0,1)))?></span><div><b><?=e($g['name'])?></b><small><?=e($g['category'])?></small></div></div></td><td><span class="badge <?=$g['checked_at']?'present':'waiting'?>"><?=$g['checked_at']?'✓ Hadir':'○ Belum hadir'?></span><?php if($g['checked_at']):?><small><?=e(date_time($g['checked_at']))?></small><?php endif;?></td><td><?php if($manage):?><a class="btn tiny ghost" href="<?=e(url('ticket',['id'=>$g['id'],'event'=>$eid]))?>"><?=icon('qr')?> Lihat QR</a><?php else:?>—<?php endif;?></td><td><div class="row-actions"><?php if($active&&!$g['checked_at']):?><button class="btn tiny primary" data-manual-code="HADIR:<?=e($g['token'])?>" data-event="<?=$eid?>" data-name="<?=e($g['name'])?>">Check-in</button><?php endif;if($manage&&$active):?><a class="text-button" href="<?=e(url('guests',['event'=>$eid,'edit'=>$g['id']]))?>">Edit</a><?php if(!$g['checked_at']):?><form method="post" data-confirm="Hapus tamu ini? QR undangan akan tidak berlaku."><?=csrf_field()?><input type="hidden" name="action" value="guest_remove"><input type="hidden" name="event_id" value="<?=$eid?>"><input type="hidden" name="id" value="<?=$g['id']?>"><button class="text-button danger">Hapus</button></form><?php endif;endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty"><span class="big-icon"><?=icon('users')?></span><h3><?=$q||$status!=='all'?'Tamu tidak ditemukan':'Daftar tamu masih kosong'?></h3><p><?=$manage?'Tambahkan tamu atau impor dari CSV.':'Tamu akan tampil setelah ditambahkan ketua acara.'?></p></div><?php endif;?><div class="panel-foot"><small>Halaman <?=$page?> / <?=$pages?> · <?=$total?> tamu</small><div class="pagination"><?php if($page>1):?><a href="<?=e(url('guests',['event'=>$eid,'q'=>$q,'status'=>$status,'p'=>$page-1]))?>">← Sebelumnya</a><?php endif;if($page<$pages):?><a href="<?=e(url('guests',['event'=>$eid,'q'=>$q,'status'=>$status,'p'=>$page+1]))?>">Berikutnya →</a><?php endif;?></div></div></section>
 <?php if($manage&&$active):dialog_start('guest-form',$edit?'Edit tamu':'Tambah tamu');?><p class="muted">QR unik otomatis dibuat untuk setiap tamu baru.</p><form method="post" <?=$edit?'data-auto-open':''?>><?=csrf_field()?><input type="hidden" name="action" value="guest_save"><input type="hidden" name="event_id" value="<?=$eid?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label>Nama tamu<input name="name" required maxlength="160" value="<?=e($edit['name']??'')?>" placeholder="Nama lengkap tamu"></label><label>Kategori<input name="category" list="categories" required maxlength="60" value="<?=e($edit['category']??'Umum')?>"><datalist id="categories"><option>Umum</option><option>VIP</option><option>Orang tua</option><option>Guru & staf</option><option>Mitra</option></datalist></label><button class="btn primary full">Simpan tamu <?=icon('check')?></button></form><?php dialog_end();dialog_start('import-form','Impor daftar tamu');?><p class="muted">CSV UTF-8 dengan pemisah koma dan header <code>nama,kategori</code>. Maksimal 1 MB / 2.000 baris. Impor ulang menambah tamu baru.</p><a class="btn small ghost" href="<?=e(url('template'))?>"><?=icon('download')?> Unduh contoh CSV</a><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="guest_import"><input type="hidden" name="event_id" value="<?=$eid?>"><label>File CSV<input type="file" name="csv" accept=".csv,text/csv" required></label><button class="btn primary full">Impor tamu</button></form><?php dialog_end();endif;
}
function render_scan(): void {$ev=selected_event();if(!$ev){empty_panel('Pilih acara terlebih dahulu.','Scanner memeriksa QR berdasarkan acara yang dipilih.');return;}page_heading('REGISTRASI TAMU','Scan. Sambut. Selesai.',$ev['name']);?><div class="scan-grid"><section class="panel scanner-panel" id="scanner" data-event="<?=$ev['id']?>"><div class="panel-heading"><div><h2>Scanner QR undangan</h2><p>Kamera diproses pada perangkat, tanpa mengunggah video.</p></div><span class="badge waiting" id="camera-status">Kamera nonaktif</span></div><div class="camera-box"><video id="camera-video" playsinline muted hidden></video><div id="camera-placeholder"><?=icon('scan')?><p>Arahkan QR tamu ke area ini</p></div><div class="scan-frame"></div></div><div class="scanner-buttons"><button class="btn primary" id="camera-start"><?=icon('scan')?> Aktifkan kamera</button><button class="btn ghost" id="camera-stop" hidden>Matikan kamera</button><button class="btn ghost" id="scan-next" hidden>Scan tamu berikutnya</button></div><p class="fine center" id="camera-help">Gunakan HTTPS dan izinkan akses kamera pada browser.</p><div id="scan-result" class="scan-result" role="status" hidden></div></section><section class="panel manual-panel"><span class="event-icon"><?=icon('users')?></span><h2>Alternatif yang tetap mudah.</h2><p>Cari nama tamu untuk check-in manual, atau masukkan kode undangan jika kamera bermasalah.</p><a class="btn ghost full" href="<?=e(url('guests',['event'=>$ev['id']]))?>"><?=icon('search')?> Cari nama tamu</a><form id="manual-scan"><label>Kode undangan<input name="code" required maxlength="80" placeholder="HADIR:…" autocomplete="off"></label><button class="btn primary full">Catat kehadiran <?=icon('check')?></button></form><div class="mini-note">✓ QR acara lain otomatis ditolak.<br>✓ Satu undangan untuk satu kehadiran.<br>✓ Tamu sudah hadir tidak dicatat ulang.</div></section></div><script src="assets/vendor/jsQR.js" defer></script><?php }
function render_users(): void {
 $u=user();$super=$u['role']==='superadmin';$edit=null;
 if(!empty($_GET['edit'])){$edit=sql('SELECT id,name,username,role,event_id,active FROM users WHERE id=?',[(int)$_GET['edit']])->fetch();if(!$edit||(!$super&&($edit['role']!=='petugas'||(int)$edit['event_id']!==(int)$u['event_id'])))throw new DomainException('Akun bukan bagian dari tim Anda.');if((int)$edit['id']===(int)$u['id'])throw new DomainException('Gunakan menu Akun saya untuk akun sendiri.');}
 page_heading('ORANG YANG TEPAT, AKSES YANG TEPAT','Tim kecil. Kerja lebih rapi.',$super?'Atur pemilik, ketua acara, dan petugas registrasi.':'Kelola petugas registrasi untuk acara Anda.','<button class="btn primary" data-dialog="user-form">'.icon('plus').' Tambah akun</button>');
 $page=max(1,(int)($_GET['p']??1));$total=(int)($super?sql('SELECT COUNT(*) FROM users')->fetchColumn():sql("SELECT COUNT(*) FROM users WHERE event_id=? AND role='petugas'",[$u['event_id']])->fetchColumn());$pages=max(1,(int)ceil($total/25));$page=min($page,$pages);$offset=($page-1)*25;
 $rows=$super?sql('SELECT u.id,u.name,u.username,u.role,u.active,u.event_id,e.name event_name FROM users u LEFT JOIN events e ON e.id=u.event_id ORDER BY u.id DESC LIMIT 25 OFFSET '.$offset)->fetchAll():sql("SELECT u.id,u.name,u.username,u.role,u.active,u.event_id,e.name event_name FROM users u LEFT JOIN events e ON e.id=u.event_id WHERE u.event_id=? AND u.role='petugas' ORDER BY u.id DESC LIMIT 25 OFFSET ".$offset,[$u['event_id']])->fetchAll();
 ?><section class="panel"><div class="table-scroll"><table><thead><tr><th>Nama / username</th><th>Peran</th><th>Acara</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><small>@<?=e($r['username'])?></small></td><td><span class="role-badge"><?=e($r['role'])?></span></td><td><?=e($r['event_name']??'Seluruh acara')?></td><td><span class="badge <?=$r['active']?'present':'waiting'?>"><?=$r['active']?'Aktif':'Nonaktif'?></span></td><td><?php if((int)$r['id']!==(int)$u['id']):?><a class="btn small ghost" href="<?=e(url('users',['edit'=>$r['id']]))?>">Kelola</a><?php else:?>Anda<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty"><h3>Belum ada petugas</h3><p>Tambahkan akun untuk tim registrasi.</p></div><?php endif;?><div class="panel-foot"><small>Halaman <?=$page?> / <?=$pages?> · <?=$total?> akun</small><div class="pagination"><?php if($page>1):?><a href="<?=e(url('users',['p'=>$page-1]))?>">← Sebelumnya</a><?php endif;if($page<$pages):?><a href="<?=e(url('users',['p'=>$page+1]))?>">Berikutnya →</a><?php endif;?></div></div></section><?php
 dialog_start('user-form',$edit?'Kelola akun':'Tambah akun');?><p class="muted">Admin dan petugas masing-masing hanya terhubung ke satu acara.</p><form method="post" <?=$edit?'data-auto-open':''?>><?=csrf_field()?><input type="hidden" name="action" value="user_save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label>Nama<input name="name" required maxlength="120" value="<?=e($edit['name']??'')?>"></label><label>Username<input name="username" required pattern="[a-z0-9_.-]{3,50}" minlength="3" maxlength="50" value="<?=e($edit['username']??'')?>" autocomplete="off"></label><?php if($super):?><div class="form-row"><label>Peran<select name="role" id="user-role"><?php foreach(['admin'=>'Admin · ketua acara','petugas'=>'Petugas registrasi','superadmin'=>'Superadmin · pemilik'] as $v=>$t):?><option value="<?=$v?>" <?=($edit['role']??'admin')===$v?'selected':''?>><?=$t?></option><?php endforeach;?></select></label><label>Penugasan acara<select name="assignment" id="user-assignment"><option value="">Pilih acara</option><?php foreach(sql('SELECT id,name FROM events WHERE status=\'active\' OR id=? ORDER BY id DESC LIMIT 500',[(int)($edit['event_id']??0)])->fetchAll() as $ev):?><option value="<?=$ev['id']?>" <?=(int)($edit['event_id']??0)===(int)$ev['id']?'selected':''?>><?=e($ev['name'])?></option><?php endforeach;?></select></label></div><?php else:?><div class="notice">Akun baru otomatis menjadi petugas di acara Anda.</div><?php endif;?><label><?=$edit?'Kata sandi baru (kosongkan jika tetap)':'Kata sandi'?><input name="password" type="password" minlength="10" maxlength="72" <?=$edit?'':'required'?> autocomplete="new-password" placeholder="Minimal 10 karakter"></label><label class="checkbox"><input type="checkbox" name="active" value="1" <?=!$edit||$edit['active']?'checked':''?>> Akun aktif</label><button class="btn primary full">Simpan akun <?=icon('check')?></button></form><?php dialog_end();
}
function render_logs(): void {$u=user();$ev=selected_event();if(!$ev&&$u['role']!=='superadmin')return;page_heading('JEJAK AKTIVITAS','Setiap tindakan, tercatat.','Riwayat perubahan terbaru untuk membantu koordinasi panitia.');$where=$ev?' WHERE a.event_id=?':'';$args=$ev?[$ev['id']]:[];$p=max(1,(int)($_GET['p']??1));$total=(int)sql('SELECT COUNT(*) FROM audit_logs a'.$where,$args)->fetchColumn();$pages=max(1,(int)ceil($total/50));$p=min($p,$pages);$rows=sql('SELECT a.*,u.name user_name,e.name event_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN events e ON e.id=a.event_id'.$where.' ORDER BY a.id DESC LIMIT 50 OFFSET '.(($p-1)*50),$args)->fetchAll();$labels=['auth.login'=>'Masuk sistem','auth.password'=>'Ganti kata sandi','event.save'=>'Simpan acara','event.status'=>'Ubah status acara','guest.save'=>'Simpan tamu','guest.remove'=>'Hapus tamu','guest.import'=>'Impor tamu','guest.checkin'=>'Check-in tamu','user.save'=>'Simpan akun'];?><section class="panel"><div class="table-scroll"><table><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aktivitas</th><th>Acara / ID target</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date_time($r['created_at']))?></td><td><?=e($r['user_name']??'Sistem')?></td><td><?=e($labels[$r['action']]??$r['action'])?></td><td><?=e($r['event_name']??'—')?><small>ID <?=e($r['target_id']??'—')?></small></td></tr><?php endforeach;?></tbody></table></div><div class="panel-foot"><small>Halaman <?=$p?> / <?=$pages?> · <?=$total?> aktivitas</small><div class="pagination"><?php $args=$ev?['event'=>$ev['id']]:[];if($p>1):?><a href="<?=e(url('logs',$args+['p'=>$p-1]))?>">← Sebelumnya</a><?php endif;if($p<$pages):?><a href="<?=e(url('logs',$args+['p'=>$p+1]))?>">Berikutnya →</a><?php endif;?></div></div></section><?php }
function render_account(): void {$u=user();page_heading('AKUN SAYA','Akses Anda, tetap terjaga.','Perbarui kata sandi secara mandiri.');?><section class="panel account-panel"><h2><?=e($u['name'])?></h2><p class="muted">@<?=e($u['username'])?> · <?=e($u['role'])?></p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="password"><label>Kata sandi saat ini<input type="password" name="current_password" required maxlength="72" autocomplete="current-password"></label><label>Kata sandi baru<input type="password" name="password" minlength="10" maxlength="72" required autocomplete="new-password" placeholder="Minimal 10 karakter"></label><button class="btn primary">Perbarui kata sandi</button></form><p class="fine">Sesi login lain akan otomatis berakhir.</p></section><?php }
function render_ticket(): void {
 role_required(['superadmin','admin']);$g=sql('SELECT * FROM guests WHERE id=? AND deleted_at IS NULL',[(int)($_GET['id']??0)])->fetch();if(!$g)throw new DomainException('Undangan tidak ditemukan.');$ev=event_access((int)$g['event_id'],true);head('Undangan '.$g['name']);?><main class="ticket-wrap"><div class="ticket-toolbar"><a class="btn ghost" href="<?=e(url('guests',['event'=>$ev['id']]))?>">← Daftar tamu</a><button class="btn primary" id="download-ticket"><?=icon('download')?> Unduh PNG</button><button class="btn ghost" id="print-ticket">Cetak</button></div><article class="ticket" id="invitation" data-code="HADIR:<?=e($g['token'])?>" data-name="<?=e($g['name'])?>" data-title="<?=e($ev['name'])?>" data-date="<?=e($ev['starts_at']?date_time($ev['starts_at']):'')?>" data-location="<?=e($ev['location'])?>" data-description="<?=e($ev['description'])?>"><div class="brand ticket-brand">hadir<span>.</span></div><div class="eyebrow">DENGAN HANGAT, KAMI MENGUNDANG</div><h1><?=e($ev['name'])?></h1><p>Kepada Yth.</p><h2><?=e($g['name'])?></h2><span class="ticket-category"><?=e($g['category'])?></span><div class="qr-frame"><canvas id="ticket-qr" aria-label="QR unik undangan"></canvas></div><p class="ticket-instruction">Tunjukkan QR ini kepada petugas registrasi.</p><div class="ticket-info"><b><?=e($ev['starts_at']?date_time($ev['starts_at']):'Tanggal akan diinformasikan')?></b><span><?=e($ev['location'])?></span></div><?php if($ev['description']):?><p class="ticket-description"><?=e($ev['description'])?></p><?php endif;?><code><?=e($g['token'])?></code><p id="ticket-error" class="notice error" hidden></p></article><p class="fine center">Satu QR berlaku untuk satu tamu. Unduh lalu bagikan gambar ini secara pribadi.</p></main><script src="assets/vendor/qrcode.js" defer></script></body></html><?php }
